<script lang="ts">
 export let active='experiences';
 export let sections: readonly { id: string; label: string; count?: number; badge?: { label: string; status: 'active' | 'selected'; description: string } }[] = [];
 function navigate(event:KeyboardEvent,index:number){let next=index;if(event.key==='ArrowDown')next=(index+1)%sections.length;else if(event.key==='ArrowUp')next=(index+sections.length-1)%sections.length;else if(event.key==='Home')next=0;else if(event.key==='End')next=sections.length-1;else return;event.preventDefault();active=sections[next].id;const nav=(event.currentTarget as HTMLElement).parentElement;nav?.querySelectorAll<HTMLButtonElement>('button')[next]?.focus();}
</script>
<div class="dashboard-contexts"><div class="tabs" role="tablist" aria-label="Dashboard" aria-orientation="vertical">{#each sections as section,index (section.id)}<button id={'dashboard-tab-'+section.id} role="tab" aria-selected={active===section.id} aria-controls="dashboard-context-panel" tabindex={active===section.id?0:-1} on:click={()=>active=section.id} on:keydown={event=>navigate(event,index)}>{section.label}{#if section.badge}<small class="tab-badge" data-badge-status={section.badge.status} title={section.badge.description} aria-label={section.badge.description}>{section.badge.label}</small>{:else if section.count!==undefined}<small>{section.count}</small>{/if}</button>{/each}</div><div id="dashboard-context-panel" role="tabpanel" aria-labelledby={'dashboard-tab-'+active} tabindex="0"><div class="dashboard-content"><slot {active}/></div></div><div class="dashboard-footer"><slot name="footer" {active}/></div></div>
<style>.dashboard-contexts{--dashboard-scrollbar-outset:10px;margin-right:calc(-1 * var(--dashboard-scrollbar-outset));height:100%;min-height:0;overflow:hidden;display:grid;grid-template-columns:160px minmax(0,1fr);gap:24px}.tabs{min-height:0;overflow:auto;display:flex;flex-direction:column;gap:5px;border-right:1px solid var(--color-border-subtle);padding-right:14px}button{font:inherit;display:flex;justify-content:space-between;text-align:left;padding:12px;border:0;border-radius:7px;background:transparent;color:var(--color-text-secondary);cursor:pointer}button[aria-selected=true]{background:var(--color-background-muted);color:var(--color-text-primary);font-weight:600}[role=tabpanel]{min-width:0;min-height:0;overflow:hidden;display:flex;flex-direction:column}.dashboard-content{flex:1;min-height:0;overflow:auto;padding-right:calc(6px + var(--dashboard-scrollbar-outset));scrollbar-gutter:stable}.dashboard-footer{flex:none;margin-right:var(--dashboard-scrollbar-outset)}small{opacity:.65}@media(max-width:600px){.dashboard-contexts{grid-template-columns:1fr}.tabs{flex-direction:row;overflow:auto;border:0;padding:0}button{white-space:nowrap}}[role=tabpanel] :global([data-dashboard-context-title]){margin:0;font-size:22px;line-height:1.3;letter-spacing:-.025em;font-weight:700}.dashboard-contexts{grid-template-rows:minmax(0,1fr) auto;row-gap:0}
.tab-badge{opacity:1;margin-inline-start:6px;align-self:center;flex:none;padding:1px 5px;border-radius:999px;font-size:.72em;line-height:1.35;color:var(--color-text-secondary);background:rgb(128 128 128 / 17%);border:1px solid rgb(150 150 150 / 34%)}
.tab-badge[data-badge-status="active"]{color:var(--color-text-primary);background:color-mix(in srgb,#28a365 35%,var(--color-background-surface));border-color:#28945d}
.tabs{grid-column:1;grid-row:1}
[role=tabpanel]{grid-column:2;grid-row:1}
.dashboard-footer{grid-column:1/-1;grid-row:2;margin-left:159px;border-top:0;padding-left:24px}
.dashboard-footer :global(.diagnostics){border:0;margin:0}
.dashboard-footer :global(.diagnostics-toolbar){padding:4px 0 0}
.dashboard-footer :global(.diagnostics section){background:var(--color-background-muted);border:1px solid var(--color-border-subtle);border-radius:5px;padding:12px;margin-top:4px}
@media(max-width:600px){.dashboard-contexts{grid-template-rows:auto minmax(0,1fr) auto}.tabs{grid-row:1}[role=tabpanel]{grid-column:1;grid-row:2}.dashboard-footer{grid-row:3;margin-left:0;padding-left:0}}
</style>